  combatProfile: SagaTreeCombatProfile;
  combatRole: SagaTreeCombatRole;
  experienceBonus: number;
  primarySkillRank: number;
  primaryModifier: number;
  defense: number;
  resistances: SagaTreeResistanceSlots;
  baseHealth: number;
  health: number;
  baseDamage: SagaTreeDamageStep;
  primaryDamage: SagaTreeDamageStep;
  attributeDefaults: readonly [number, number, number, number, number, number];
  movementMeters: number;
  threatUnitsSameLevel: number;
  impulsesPerRound: number;
  wendepunktPerCombat: number;
  signatureAbilityBudget: number;
  minImpulseOptions: number;
  impulsesAllowed: boolean;
  combatSignatureRequired: boolean;
  requiresRangedPrimary: boolean;
  primaryAttackDelta: number;
  meleeAttackDelta: number;
  rangedAttackDelta: number;
  controlEffectDelta: number;
};

export type AtlasBiomeBrushSpec = {
  readonly id: AtlasBiomeBrushId;
  readonly labelDe: string;
  readonly swatchHex: string;
  readonly material: UnifiedCanvasMaterial;
};

export type AtlasFeatureAuthority =
  | AtlasFeatureOwner
  | 'view'
  | 'atmospheric'
  | 'hierarchy'
  | 'unresolved';

export type AtlasCanonicalFeatureRef = {
  readonly kind: AtlasCanonicalFeatureKind;
  readonly id: string;
  readonly authority: AtlasFeatureAuthority;
  /** V1 storage slot this classification was derived from. */
  readonly v1Slot: 'stroke' | 'room' | 'wall' | 'object' | 'layer' | 'meta' | 'hierarchy';
  readonly secret?: boolean;
};

export type AtlasMigrationDisposition =
  | 'keep'
  | 'classify_only'
  | 'review_queue'
  | 'reject_parse'
  | 'deferred_ticket';

export type AtlasMigrationMatrixRow = {
  readonly source: string;
  readonly disposition: AtlasMigrationDisposition;
  readonly notes: string;
};

export type AtlasCanonicalDocClassification = {
  readonly catalogVersion: typeof ATLAS_CANONICAL_CATALOG_VERSION;
  readonly wireDecision: typeof ATLAS_WIRE_FORMAT_DECISION;
  readonly features: readonly AtlasCanonicalFeatureRef[];
  readonly counts: Readonly<Record<AtlasCanonicalFeatureKind, number>>;
};

export type ClassifyUnifiedCanvasOptions = {
  readonly scale?: 'world' | 'interior' | 'unknown';
  /** When true, apply Golden stroke-id heuristics; never use material alone. */
