};

export type AtlasZoomTransitionIntent =
  | { readonly kind: 'none' }
  | {
      readonly kind: 'enter-child';
      readonly pin: AtlasMapPin;
      readonly distance: number;
    }
  | {
      readonly kind: 'exit-parent';
    };

export type AtlasScaleLabelSpec = {
  readonly scale: AtlasMapScale;
