    if (!MAP_PIN_ALLOWED_MIME.has(prepared.type)) {
      throw new Error('Nur PNG, JPEG oder WebP sind als Pin-Bild erlaubt.');
    }
    const published = await publishHostWorldAsset(id, prepared, 'map-pin');
    return published.storagePath;
  }

